android.extraProguardRules:
# Código nativo que React Native, Expo y estas librerías llaman por JNI o reflexión: R8 no debe renombrarlo ni quitarlo.
-keep class com.facebook.react.** { *; }
-keep class com.facebook.hermes.** { *; }
-keep class com.facebook.jni.** { *; }
-keep class com.facebook.soloader.** { *; }
-keep class expo.modules.** { *; }
-keep class com.swmansion.reanimated.** { *; }
-keep class com.swmansion.worklets.** { *; }
-keep class com.swmansion.gesturehandler.** { *; }
-keep class com.swmansion.rnscreens.** { *; }
-keep class com.horcrux.svg.** { *; }
-keep class com.th3rdwave.safeareacontext.** { *; }
-keepclassmembers class * { @com.facebook.react.bridge.ReactMethod *; @com.facebook.proguard.annotations.DoNotStrip *; }
-dontwarn com.facebook.**
-dontwarn expo.modules.**
# expo-notifications trae Firebase Messaging aunque la app solo usa avisos locales (sin push).
-dontwarn com.google.firebase.**
